using Microsoft.AspNetCore.Mvc; using Exercicio13_Pedidos.Models; namespace Exercicio13_Pedidos.Controllers; public class PedidoController:Controller{private static readonly List<Pedido> Dados=new(){new(){Id=1,Cliente="Cliente 1",Produto="Lanche 1",Quantidade=2,PrecoUnitario=11,Status="Recebido"},new(){Id=2,Cliente="Cliente 2",Produto="Lanche 2",Quantidade=3,PrecoUnitario=12,Status="Em preparo"},new(){Id=3,Cliente="Cliente 3",Produto="Lanche 3",Quantidade=4,PrecoUnitario=13,Status="Pronto"},new(){Id=4,Cliente="Cliente 4",Produto="Lanche 4",Quantidade=1,PrecoUnitario=14,Status="Entregue"},new(){Id=5,Cliente="Cliente 5",Produto="Lanche 5",Quantidade=2,PrecoUnitario=15,Status="Recebido"},new(){Id=6,Cliente="Cliente 6",Produto="Lanche 6",Quantidade=3,PrecoUnitario=16,Status="Em preparo"},new(){Id=7,Cliente="Cliente 7",Produto="Lanche 7",Quantidade=4,PrecoUnitario=17,Status="Pronto"},new(){Id=8,Cliente="Cliente 8",Produto="Lanche 8",Quantidade=1,PrecoUnitario=18,Status="Entregue"},new(){Id=9,Cliente="Cliente 9",Produto="Lanche 9",Quantidade=2,PrecoUnitario=19,Status="Recebido"},new(){Id=10,Cliente="Cliente 10",Produto="Lanche 10",Quantidade=3,PrecoUnitario=20,Status="Em preparo"},}public IActionResult Index()=>View(Dados); public IActionResult EmPreparo()=>View("Index",Dados.Where(x=>x.Status=="Em preparo")); public IActionResult Prontos()=>View("Index",Dados.Where(x=>x.Status=="Pronto")); public IActionResult Entregues()=>View("Index",Dados.Where(x=>x.Status=="Entregue")); public IActionResult Dashboard()=>View(Dados);}
